package dev.codesomething.lab;
import org.springframework.web.bind.annotation.*;
@RestController
public class DemoController {
    @GetMapping(value="/",produces="text/html;charset=UTF-8") public String page(){return """
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>学习计划与任务协作</title>
<style>
:root{color-scheme:light;--base:oklch(97.788% .004 56.375);--layer:oklch(93.982% .007 61.449);--ink:oklch(23.574% .066 313.189);--primary:oklch(85% .138 181.071);--on-primary:oklch(43% .078 188.216)}
*{box-sizing:border-box}body{margin:0;background:var(--base);color:var(--ink);font:16px/1.7 system-ui,'Microsoft YaHei',sans-serif}main{max-width:960px;margin:auto;padding:32px 20px}.skip{position:absolute;left:-10000px}.skip:focus{left:16px;top:8px;background:var(--base);padding:8px}h1{font-size:28px;line-height:1.3}h2{font-size:21px}h1,h2{text-wrap:balance}textarea{color:var(--ink);background:var(--base);border:1px solid var(--ink);border-radius:8px;padding:8px}#pagination{font-variant-numeric:tabular-nums}section{padding:24px 0;border-top:1px solid color-mix(in oklab,var(--ink) 22%,var(--base))}label{display:grid;gap:6px;min-width:0;max-width:100%}form,.row{display:flex;flex-wrap:wrap;align-items:end;gap:12px}input,select,button{font:inherit;min-height:44px;border:1px solid color-mix(in oklab,var(--ink) 35%,var(--base));border-radius:8px;padding:8px 12px;background:var(--base);color:var(--ink);max-width:100%}button{cursor:pointer}button.primary{background:var(--primary);color:var(--on-primary)}button:disabled{opacity:.55;cursor:wait}input{width:220px}a{color:inherit}li{margin:12px 0}pre{padding:16px;background:var(--layer);white-space:pre-wrap;overflow-wrap:anywhere}#feedback{min-height:2em;overflow-wrap:anywhere}:focus-visible{outline:3px solid var(--on-primary);outline-offset:3px}small{font-size:14px}.task{display:flex;justify-content:space-between;gap:12px;align-items:center}.task span{overflow-wrap:anywhere}[hidden]{display:none!important}@media(max-width:480px){form>label,form>button{width:100%}input{width:100%}.task{align-items:start;flex-direction:column}}
</style><a class="skip" href="#main">跳到主要内容</a><main id="main" tabindex="-1"><h1>学习计划与任务协作</h1><p>登录后查看自己的计划、筛选任务，再验证负责人和成员的操作范围。</p>
<section id="login"><h2>登录</h2><form id="login-form"><label>账号<input id="username" name="username" spellcheck="false" autocomplete="username" required maxlength="80"></label><label>密码<input id="password" name="password" type="password" autocomplete="current-password" required maxlength="200"></label><button class="primary">登录</button></form><details><summary>本地练习账号</summary><p>alice（计划1负责人）、bob（计划1成员）、eve（计划2负责人）、admin（审计管理员）。练习密码均为Learn-2026!。这些是隔离教学数据。</p></details></section>
<p id="feedback" tabindex="-1" role="status" aria-live="polite"></p>
<div id="workspace" hidden><div class="row"><strong id="identity"></strong><button id="logout">退出登录</button></div>
<section><h2>我的计划</h2><form id="plan-form"><label>新计划名称<input name="title" autocomplete="off" id="plan-title" required maxlength="100"></label><button>创建计划</button></form><ul id="plans"></ul></section>
<section><h2 id="task-heading">计划任务</h2><form id="filter-form"><label>计划编号<input name="planId" inputmode="numeric" id="plan-id" type="number" min="1" value="1" required></label><label>任务状态<select name="status" id="status"><option value="all">全部</option><option value="todo">未完成</option><option value="done">已完成</option></select></label><button>查询任务</button></form><ul id="tasks"></ul><div class="row"><button id="previous">上一页</button><span id="pagination"></span><button id="next">下一页</button></div></section>
<section><h2>批量分配任务</h2><p>负责人每行输入“成员编号|任务标题”。整批一起成功或回滚，成员编号可用alice=1、bob=2。</p><form id="batch-form"><label>任务清单<textarea name="batch" autocomplete="off" id="batch" rows="4" required style="font:inherit;max-width:100%;width:100%;min-width:0"></textarea></label><button>分配任务</button></form></section>
<section><h2>权限与审计</h2><p>用上方计划编号查询他人计划，可核对403拒绝。普通成员分配任务也会被拒绝。</p><button id="audit">查看管理员审计</button><pre id="audit-result" tabindex="0" aria-label="审计结果">尚未查询</pre></section></div></main>
<script>
let token='',page=0,total=0;const $=id=>document.getElementById(id);const feedback=(message,error=false)=>{$('feedback').setAttribute('role',error?'alert':'status');$('feedback').textContent=message;if(error)$('feedback').focus()};
async function api(path,method='GET',body){const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});const result=response.status===204?null:await response.json();if(!response.ok){if(response.status===401){token='';$('workspace').hidden=true;$('login').hidden=false}throw new Error(response.status+' · '+result.message+' · 请求编号 '+result.requestId)}return result}
async function action(button,work){const label=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='处理中…';try{await work()}catch(error){feedback(error.message,true)}finally{button.disabled=false;button.removeAttribute('aria-busy');button.textContent=label}}
async function plans(){const items=await api('/plans');$('plans').replaceChildren();for(const item of items){const li=document.createElement('li'),button=document.createElement('button');button.textContent=item.id+' · '+item.title;button.onclick=()=>action(button,async()=>{$('plan-id').value=item.id;page=0;await tasks()});li.append(button);$('plans').append(li)}if(!items.length)$('plans').textContent='暂无计划，创建一个开始。';return items}
async function tasks(){$('tasks').replaceChildren();$('pagination').textContent='正在读取…';$('previous').disabled=true;$('next').disabled=true;const plan=$('plan-id').value;if(!/^\\d+$/.test(plan)||Number(plan)<1)throw new Error('请填写有效计划编号');const result=await api('/plans/'+plan+'/tasks?page='+page+'&size=2&status='+$('status').value);total=result.total;$('tasks').replaceChildren();for(const task of result.items){const li=document.createElement('li'),span=document.createElement('span'),button=document.createElement('button');li.className='task';span.textContent=task.id+' · '+task.title+' · '+(task.status==='done'?'已完成':'未完成')+' · 成员'+task.assigneeId;button.textContent='完成任务 '+task.id;button.disabled=task.status==='done';button.onclick=()=>action(button,async()=>{await api('/plans/'+plan+'/tasks/'+task.id+'/complete','PUT');await tasks();feedback('任务已完成')});li.append(span,button);$('tasks').append(li)}if(!result.items.length)$('tasks').textContent='当前筛选没有任务。';$('pagination').textContent='第'+(page+1)+'页 · 共'+total+'条';$('previous').disabled=page===0;$('next').disabled=(page+1)*2>=total}
$('login-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const result=await api('/auth/login','POST',{username:$('username').value,password:$('password').value});token=result.token;$('password').value='';$('identity').textContent=result.username+' · '+result.role;$('workspace').hidden=false;$('login').hidden=true;page=0;$('tasks').replaceChildren();$('pagination').textContent='';$('audit-result').textContent='尚未查询';const items=await plans();if(items.length){$('plan-id').value=items[0].id;await tasks()}feedback('登录成功，令牌仅保存在当前页面内存中')})};
$('logout').onclick=e=>action(e.currentTarget,async()=>{await api('/auth/session','DELETE');token='';$('workspace').hidden=true;$('login').hidden=false;$('audit-result').textContent='尚未查询';$('tasks').replaceChildren();$('plans').replaceChildren();$('pagination').textContent='';feedback('已退出，旧会话立即失效');$('username').focus()});
$('plan-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const result=await api('/plans','POST',{title:$('plan-title').value});$('plan-title').value='';$('plan-id').value=result.id;page=0;await plans();await tasks();feedback('计划已创建，已加入负责人本人')})};
$('filter-form').onsubmit=e=>{e.preventDefault();page=0;action(e.submitter,async()=>{await tasks();feedback('任务已更新')})};
$('previous').onclick=e=>action(e.currentTarget,async()=>{page=Math.max(0,page-1);await tasks()});$('next').onclick=e=>action(e.currentTarget,async()=>{page++;await tasks()});
$('batch-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const items=$('batch').value.split('\\n').filter(x=>x.trim()).map(line=>{const position=line.indexOf('|');return {assigneeId:Number(line.slice(0,position)),title:position<0?'':line.slice(position+1)}});const result=await api('/plans/'+$('plan-id').value+'/tasks/batch','POST',items);page=0;await tasks();feedback('成功分配'+result.created+'条任务');$('batch').value=''})};
$('audit').onclick=e=>action(e.currentTarget,async()=>{$('audit-result').textContent=JSON.stringify(await api('/admin/audit'),null,2);feedback('已读取审计记录')});
</script></html>
""";}
}
